), missing_relations AS (
 SELECT e.name,e.kind AS required_kind FROM expected_relations e
 LEFT JOIN actual_relations a ON a.name=e.name WHERE a.oid IS NULL
), kind_differences AS (
 SELECT e.name,e.kind AS required_kind,a.kind AS actual_kind FROM expected_relations e
 JOIN actual_relations a ON a.name=e.name WHERE e.kind<>a.kind
), missing_columns AS (
 SELECT e.relation,e.name FROM expected_columns e JOIN actual_relations a ON a.name=e.relation
 LEFT JOIN pg_catalog.pg_attribute t ON t.attrelid=a.oid AND t.attname=e.name AND t.attnum>0 AND NOT t.attisdropped
 WHERE t.attnum IS NULL
)
SELECT jsonb_build_object(
 'scope','EXISTENCE_AND_RELATION_KIND_ONLY_NOT_RELEASE_CERTIFICATION',
 'expected_project_for_independent_operator_confirmation','bcvfosxcyvarieiinovo',
 'project_identity_verified_by_sql',false,
 'actor',current_user,'server_version',current_setting('server_version'),
 'missing_relations',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.name),'[]'::jsonb) FROM missing_relations x),
 'relation_kind_differences',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.name),'[]'::jsonb) FROM kind_differences x),
 'missing_columns_on_present_relations',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.relation,x.name),'[]'::jsonb) FROM missing_columns x),
 'unverified','Types, constraints, indexes, functions, triggers, RLS, grants, permission assignments, migration receipts, attestations and application acceptance'
) AS private_development_object_findings;
